testo:
{
 "genere": "prevedi",
 "titolo": "Cosa restituisce?",
 "consegna": "Leggi ogni pezzo di codice e scrivi cosa restituisce `run()`, senza eseguirlo. Poi confronta con la risposta vera.",
 "modalita": "previsioni",
 "previsioni": [
  {
   "codice": "extends StaticBody2D


func run():
	collision_layer = 5
	return collision_layer
",
   "domanda": "Quanto vale `collision_layer` alla fine?",
   "spiegazione": "`collision_layer` è un numero intero che rappresenta i layer attivi come bit. 5 corrisponde ai layer 1 e 3 (1 + 4 = 5)."
  },
  {
   "codice": "extends StaticBody2D


func run():
	collision_mask = 2
	var collides: bool = (collision_mask & 2) != 0
	return collides
",
   "domanda": "`collides` è vero o falso alla fine?",
   "spiegazione": "`collision_mask` è impostato a 2. L'operazione `& 2` verifica se il bit del layer 2 è attivo. Poiché lo è, restituisce vero."
  },
  {
   "codice": "extends StaticBody2D


func run():
	collision_layer = 1
	collision_layer |= 4
	return collision_layer
",
   "domanda": "Quanto vale `collision_layer` alla fine?",
   "spiegazione": "`collision_layer` parte da 1. L'operatore `|= 4` aggiunge il layer 3 (valore 4) tramite un'operazione bit a bit. 1 + 4 fa 5."
  },
  {
   "codice": "extends StaticBody2D


func run():
	collision_mask = 4
	var checks_layer_one: bool = (collision_mask & 1) != 0
	return checks_layer_one
",
   "domanda": "`checks_layer_one` è vero o falso alla fine?",
   "spiegazione": "`collision_mask` è 4 (solo layer 3). Controllare il layer 1 (`& 1`) dà 0, quindi la condizione `!= 0` è falsa."
  },
  {
   "codice": "extends StaticBody2D


func run():
	collision_layer = 2
	collision_mask = 2
	return collision_layer == collision_mask
",
   "domanda": "Cosa restituisce `run()`?",
   "spiegazione": "Sia `collision_layer` che `collision_mask` vengono impostati a 2, quindi il confronto di uguaglianza restituisce vero."
  }
 ]
}
